#!/usr/bin/env python3
"""
Génère les icônes d'Enquêtes : un E capital en Fraunces (wght 700, opsz 144,
WONK activé), terracotta sur fond encre.

Le tracé du glyphe est figé ci-dessous : aucune police à installer, aucun
réseau. Régénère toutes les tailles en une commande.

    python3 make_icon.py

Nécessite cairosvg pour les PNG :  pip install cairosvg
"""

ENCRE = "#2E2A26"
TERRACOTTA = "#C0673A"

# Glyphe « E » de Fraunces, converti en tracé SVG (unitsPerEm = 2000)
GLYPHE = "M487.9964599609375 745.599365234375H707.999267578125Q797.1988525390625 745.599365234375 840.6985778808594 785.4992065429688Q884.1983032226562 825.3990478515625 900.7979736328125 933.99853515625Q902.39794921875 940.9984741210938 904.4979248046875 942.8984680175781Q906.597900390625 944.7984619140625 909.1978759765625 944.7984619140625Q917.3978271484375 945.198486328125 920.3978271484375 933.198486328125L1032.79736328125 561.2000732421875Q1034.79736328125 555.60009765625 1033.3973693847656 552.0001220703125Q1031.9973754882812 548.400146484375 1029.1973876953125 546.8001708984375Q1026.597412109375 546.0001831054688 1023.4974365234375 545.9002075195312Q1020.3974609375 545.8002319335938 1015.197509765625 550.8001708984375Q962.7979125976562 620.1998901367188 921.4981994628906 657.7997436523438Q880.198486328125 695.3995971679688 836.8987121582031 709.6995544433594Q793.5989379882812 723.99951171875 735.9991455078125 723.99951171875H487.9964599609375ZM65.2001953125 1392.800048828125Q65.2001953125 1395.6000366210938 67.90017700195312 1397.8000183105469Q70.60015869140625 1400 76.0001220703125 1400H970.7977294921875Q994.3976440429688 1400 1014.1975708007812 1406.1000366210938Q1033.9974975585938 1412.2000732421875 1047.4974365234375 1418.3001098632812Q1060.9973754882812 1424.400146484375 1064.79736328125 1424.400146484375Q1067.5973510742188 1424.400146484375 1069.4973449707031 1420.5001831054688Q1071.3973388671875 1416.6002197265625 1074.3973388671875 1402.4002685546875L1167.5970458984375 1014.8021240234375Q1169.5970458984375 1007.002197265625 1168.1970520019531 1003.9022216796875Q1166.7970581054688 1000.80224609375 1163.9970703125 999.2022705078125Q1161.3970947265625 998.4022827148438 1158.6971130371094 999.7022705078125Q1155.9971313476562 1001.0022583007812 1151.59716796875 1006.4022216796875Q1071.3980102539062 1122.6015014648438 1009.0986022949219 1195.3010864257812Q946.7991943359375 1268.0006713867188 894.8996276855469 1308.2004699707031Q843.0000610351562 1348.4002685546875 795.3003845214844 1363.4002075195312Q747.6007080078125 1378.400146484375 696.4010009765625 1378.400146484375H543.99609375V68.7996826171875Q543.99609375 45.19976806640625 556.7960815429688 33.399810791015625Q569.5960693359375 21.599853515625 593.5960693359375 21.599853515625H710.2008666992188Q771.80078125 21.599853515625 836.5003051757812 57.999603271484375Q901.1998291015625 94.39935302734375 982.5990600585938 194.49880981445312Q1063.998291015625 294.5982666015625 1173.7973022460938 486.79736328125Q1178.197265625 492.19732666015625 1180.8972473144531 494.2973327636719Q1183.5972290039062 496.3973388671875 1186.5972290039062 494.79736328125Q1189.5972290039062 493.99737548828125 1190.897216796875 490.0973815917969Q1192.1972045898438 486.1973876953125 1190.1972045898438 477.9974365234375L1078.5975952148438 -2.000244140625Q1075.5975952148438 -16.00018310546875 1073.6976013183594 -20.200164794921875Q1071.797607421875 -24.400146484375 1068.9976196289062 -24.400146484375Q1063.99755859375 -24.400146484375 1050.1976013183594 -18.30010986328125Q1036.3976440429688 -12.2000732421875 1015.4976501464844 -6.10003662109375Q994.59765625 0 966.9974975585938 0H76.0001220703125Q70.60015869140625 0 67.90017700195312 2.29998779296875Q65.2001953125 4.5999755859375 65.2001953125 7.199951171875Q65.2001953125 13.59991455078125 79.2000732421875 15.9998779296875L147.600830078125 27.199951171875Q169.000732421875 30.7999267578125 179.50067138671875 37.39990234375Q190.0006103515625 43.9998779296875 190.0006103515625 55.9998779296875V1344.0001220703125Q190.0006103515625 1356.0001220703125 179.50067138671875 1362.7001037597656Q169.000732421875 1369.4000854492188 147.600830078125 1372.800048828125L79.2000732421875 1384.0001220703125Q65.2001953125 1386.4000854492188 65.2001953125 1392.800048828125Z"
BBOX = (65, -24, 1192, 1424)


def svg(maskable=False):
    xmin, ymin, xmax, ymax = BBOX
    largeur, hauteur = xmax - xmin, ymax - ymin

    # 72% du cadre en usage normal ; 58% pour la maskable, afin que le
    # glyphe reste dans la zone sûre du masque Android (cercle de 80%)
    zone = 512 * (0.58 if maskable else 0.72)
    echelle = zone / hauteur
    tx = 256 - (xmin + largeur / 2) * echelle
    ty = 256 + (ymin + hauteur / 2) * echelle

    if maskable:
        # Plein bord : Android applique sa propre forme par-dessus
        cadre = '<rect x="-6" y="-6" width="524" height="524" fill="%s"/>' % ENCRE
    else:
        cadre = ('<rect x="0" y="0" width="512" height="512" '
                 'rx="117" ry="117" fill="%s"/>' % ENCRE)

    return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="512" height="512">
  <title>Enquêtes</title>
  {cadre}
  <g transform="translate({tx:.2f} {ty:.2f}) scale({echelle:.5f} -{echelle:.5f})">
    <path fill="{TERRACOTTA}" d="{GLYPHE}"/>
  </g>
</svg>
'''


if __name__ == "__main__":
    open("icon.svg", "w", encoding="utf-8").write(svg(False))
    open("icon-maskable.svg", "w", encoding="utf-8").write(svg(True))

    try:
        import cairosvg
    except ImportError:
        print("SVG générés. Installe cairosvg pour produire les PNG.")
        raise SystemExit

    for nom, source, taille in [
        ("icon.png", "icon.svg", 192),
        ("icon-192.png", "icon.svg", 192),
        ("icon-512.png", "icon.svg", 512),
        ("icon-maskable-512.png", "icon-maskable.svg", 512),
    ]:
        cairosvg.svg2png(url=source, write_to=nom,
                         output_width=taille, output_height=taille)
        print(f"  {nom}  ({taille}x{taille})")
